li class="leftmenu"><a href="/text-italic-in-css">Text Italic in CSS</a></li><li class="leftmenu"><a href="/removing-underline-from-the-link-in-css">Removing Underline from the Link in CSS</a></li><li class="leftmenu"><a href="/vw-in-css">VW in CSS</a></li><li class="leftmenu"><a href="/responsive-css-code">Responsive CSS Code</a></li><li class="leftmenu"><a href="/webkit-css">WebKit CSS</a></li><li class="leftmenu"><a href="/responsive-image-gallery-html-css">Responsive Image Gallery HTML CSS</a></li><li class="leftmenu"><a href="/1fr-in-css">1fr in CSS</a></li><li class="leftmenu"><a href="/shorthand-property-in-css">Shorthand Property in CSS</a></li><li class="leftmenu"><a href="/css-active">CSS Active</a></li><li class="leftmenu"><a href="/text-on-image-using-css">Text on Image Using CSS</a></li><li class="leftmenu"><a href="/css-align-self">CSS Align Self</a></li><li class="leftmenu"><a href="/vertical-line-in-css">Vertical Line in CSS</a></li><li class="leftmenu"><a href="/css-border-bottom">CSS Border Bottom</a></li><li class="leftmenu"><a href="/visibility-hidden-and-display-none-in-css">Visibility Hidden and Display None in CSS</a></li><li class="leftmenu"><a href="/css-border-opacity">CSS Border Opacity</a></li><li class="leftmenu"><a href="/css-custom-font">CSS Custom Font</a></li><li class="leftmenu"><a href="/css-border-opacity-benefits">CSS Border Opacity Benefits</a></li><li class="leftmenu"><a href="/css-before-hover">CSS before :hover</a></li><li class="leftmenu"><a href="/css-box-shadow-bottom-only">CSS Box-Shadow Bottom Only</a></li><li class="leftmenu"><a href="/css-checkbox-size">CSS Checkbox Size</a></li><li class="leftmenu"><a href="/css-button-click-effect">CSS Button Click Effect</a></li><li class="leftmenu"><a href="/css-code-for-blue">CSS Code for Blue</a></li><li class="leftmenu"><a href="/css-capitalize">CSS Capitalize</a></li><li class="leftmenu"><a href="/css-codes-list">CSS Codes List</a></li><li class="leftmenu"><a href="/css-child-selector">CSS Child Selector</a></li><li class="leftmenu"><a href="/css-color-red">CSS Color Red</a></li><li class="leftmenu"><a href="/css-circle">CSS Circle</a></li><li class="leftmenu"><a href="/css-compressor">CSS Compressor</a></li><li class="leftmenu"><a href="/css-clear-property">CSS Clear Property</a></li><li class="leftmenu"><a href="/css-curved-border">CSS Curved Border</a></li><li class="leftmenu"><a href="/css-content-svg">CSS Content SVG</a></li><li class="leftmenu"><a href="/css-disabled">CSS Disabled</a></li><li class="leftmenu"><a href="/css-darken-image">CSS Darken Image</a></li><li class="leftmenu"><a href="/css-display-inline">CSS Display Inline</a></li><li class="leftmenu"><a href="/css-diner">CSS Diner</a></li><li class="leftmenu"><a href="/css-display-none">CSS Display None</a></li><li class="leftmenu"><a href="/css-filter-property">CSS Filter Property</a></li><li class="leftmenu"><a href="/css-display-table">CSS Display Table</a></li><li class="leftmenu"><a href="/css-font-stack">CSS Font Stack</a></li><li class="leftmenu"><a href="/css-divs-side-by-side">CSS Divs Side by Side</a></li><li class="leftmenu"><a href="/css-grayscale">CSS Grayscale</a></li><li class="leftmenu"><a href="/css-drop-shadow-font">CSS Drop Shadow Font</a></li><li class="leftmenu"><a href="/css-hacks">CSS Hacks</a></li><li class="leftmenu"><a href="/css-flexbox-best-suited-for">CSS Flexbox Best Suited For</a></li><li class="leftmenu"><a href="/css-header-styles">CSS Header Styles</a></li><li class="leftmenu"><a href="/css-flexbox-space-between">CSS Flexbox Space Between</a></li><li class="leftmenu"><a href="/css-hero-image">CSS Hero Image</a></li><li class="leftmenu"><a href="/css-flexible-box-layout-is-best-suited-for">CSS Flexible Box Layout is Best Suited For</a></li><li class="leftmenu"><a href="/css-iframe-style">CSS Iframe Style</a></li><li class="leftmenu"><a href="/css-flip-image">CSS Flip Image</a></li><li class="leftmenu"><a href="/css-image-effects">CSS Image Effects</a></li><li class="leftmenu"><a href="/css-float-center">CSS Float Center</a></li><li class="leftmenu"><a href="/css-invert">CSS Invert</a></li><li class="leftmenu"><a href="/css-float-left">CSS Float Left</a></li><li class="leftmenu"><a href="/css-parent-selector">CSS Parent Selector</a></li><li class="leftmenu"><a href="/css-float-right">CSS Float Right</a></li><li class="leftmenu"><a href="/css-prevent-line-breaks">CSS Prevent Line Breaks</a></li><li class="leftmenu"><a href="/css-focus">CSS Focus</a></li><li class="leftmenu"><a href="/css-rotate-text">CSS Rotate Text</a></li><li class="leftmenu"><a href="/css-font-shorthand">CSS Font Shorthand</a></li><li class="leftmenu"><a href="/css-select-all-children">CSS Select All Children</a></li><li class="leftmenu"><a href="/css-form-styling">CSS Form Styling</a></li><li class="leftmenu"><a href="/css-shapes">CSS Shapes</a></li><li class="leftmenu"><a href="/css-grid-column">CSS Grid Column</a></li><li class="leftmenu"><a href="/css-spacing">CSS Spacing</a></li><li class="leftmenu"><a href="/css-grid-responsive">CSS Grid Responsive</a></li><li class="leftmenu"><a href="/css-styles-for-dropdownlist">CSS Styles for Dropdownlist</a></li><li class="leftmenu"><a href="/css-half-circle">CSS Half Circle</a></li><li class="leftmenu"><a href="/css-style-parent-based-on-child">CSS Style Parent based on Child</a></li><li class="leftmenu"><a href="/css-hover-animation">CSS Hover Animation</a></li><li class="leftmenu"><a href="/css-text-anchor">CSS Text Anchor</a></li><li class="leftmenu"><a href="/css-hover-transitions">CSS Hover Transitions</a></li><li class="leftmenu"><a href="/css-transform-rotate">CSS Transform Rotate</a></li><li class="leftmenu"><a href="/css-layers">CSS Layers</a></li><li class="leftmenu"><a href="/css-tricks-for-flexbox">CSS Tricks for Flexbox</a></li><li class="leftmenu"><a href="/css-line-break">CSS Line Break</a></li><li class="leftmenu"><a href="/css-border-radius-circle">CSS Border Radius Circle</a></li><li class="leftmenu"><a href="/css-margin-left">CSS Margin-left</a></li><li class="leftmenu"><a href="/css-colorful-text">CSS Colorful Text</a></li><li class="leftmenu"><a href="/css-media-types">CSS Media Types</a></li><li class="leftmenu"><a href="/css-images-grid">CSS Images Grid</a></li><li class="leftmenu"><a href="/css-multiple-classes">CSS Multiple Classes</a></li><li class="leftmenu"><a href="/css-profile-login">CSS Profile Login</a></li><li class="leftmenu"><a href="/css-normalisation">CSS Normalisation</a></li><li class="leftmenu"><a href="/css-runner">CSS Runner</a></li><li class="leftmenu"><a href="/css-normalization">CSS Normalization</a></li><li class="leftmenu"><a href="/fit-to-the-parent-height-in-css">Fit to the Parent Height in CSS</a></li><li class="leftmenu"><a href="/css-not-first-child">CSS Not: First-child</a></li><li class="leftmenu"><a href="/freecodecamp-html-css">FreeCodeCamp HTML CSS</a></li><li class="leftmenu"><a href="/css-not-last-of-type">CSS :Not(:last-of-type)</a></li><li class="leftmenu"><a href="/how-to-set-opacity-of-background-image-in-css">How to Set Opacity of Background Image in CSS</a></li><li class="leftmenu"><a href="/css-not-selector">CSS Not Selector</a></li><li class="leftmenu"><a href="/how-to-use-and-style-borders-using-css">How to Use and Style Borders using CSS</a></li><li class="leftmenu"><a href="/css-onclick">CSS Onclick</a></li><li class="leftmenu"><a href="/is-css-responsive-for-web-design">Is CSS Responsive for Web Design</a></li><li class="leftmenu"><a href="/css-on-hover-image-zoom">CSS on Hover Image Zoom</a></li><li class="leftmenu"><a href="/linear-gradient-background-image-in-css">Linear Gradient Background Image in CSS</a></li><li class="leftmenu"><a href="/css-opacity-border">CSS Opacity Border</a></li><li class="leftmenu"><a href="/responsive-image-gallery-in-html-css">Responsive Image Gallery in HTML CSS</a></li><li class="leftmenu"><a href="/css-override">CSS Override</a></li><li class="leftmenu"><a href="/scss-compiler-online">SCSS Compiler Online</a></li><li class="leftmenu"><a href="/css-override-class">CSS Override Class</a></li><li class="leftmenu"><a href="/selection-css">Selection CSS</a></li><li class="leftmenu"><a href="/css-plus-selector">CSS + Selector</a></li><li class="leftmenu"><a href="/set-the-divi-gutter-width-with-css">Set the Divi Gutter Width with CSS</a></li><li class="leftmenu"><a href="/css-popup">CSS Popup</a></li><li class="leftmenu"><a href="/shorthand-property-css">Shorthand Property CSS</a></li><li class="leftmenu"><a href="/css-position-absolute-relative-to-parent">CSS Position Absolute Relative to Parent</a></li><li class="leftmenu"><a href="/css-position-relative-to-parent">CSS Position Relative to Parent</a></li><li class="leftmenu"><a href="/css-progress-bars">CSS Progress Bars</a></li><li class="leftmenu"><a href="/css-prototyping">CSS Prototyping</a></li><li class="leftmenu"><a href="/css-pull-right">CSS Pull Right</a></li><li class="leftmenu"><a href="/css-reference-sheet">CSS Reference Sheet</a></li><li class="leftmenu"><a href="/css-remove-border">CSS Remove Border</a></li></ul></div></div></div><div class="accordion-item" style="background-color:var(--sidebar)"><h2 class="accordion-header" id="flush-heading6"><button aria-controls="flush-collapse6" aria-expanded="true" class="accordion-button sidebar-btn" data-bs-target="#flush-collapse6" data-bs-toggle="collapse" type="button">CSS MCQ</button></h2><div aria-labelledby="flush-heading6" class="accordion-collapse collapse show" id="flush-collapse6"><div class="accordion-body"><ul><li class="leftmenu"><a href="/css-mcq">CSS MCQ</a></li></ul></div></div></div><div class="accordion-item" style="background-color:var(--sidebar)"><h2 class="accordion-header" id="flush-heading7"><button aria-controls="flush-collapse7" aria-expanded="true" class="accordion-button sidebar-btn" data-bs-target="#flush-collapse7" data-bs-toggle="collapse" type="button">Interview Questions</button></h2><div aria-labelledby="flush-heading7" class="accordion-collapse collapse show" id="flush-collapse7"><div class="accordion-body"><ul><li class="leftmenu"><a href="/css-interview-questions">CSS Interview Questions</a></li></ul></div></div></div></div></div></div><div class="col-12 col-md-7"><div class="overview"><div id="city"><table><tbody><tr><td><div id="bottomnextup"><a class="next" href="what-is-css">next →</a></div><h1 class="h1">CSS Tutorial</h1><div style="font-size:14px;margin-top:5px;margin-bottom:5px;color:#6f6e6e"><span>24 Jul 2025</span> | <span><i aria-hidden="true" class="fa fa-clock-o"></i> 11 min read</span></div><p>If you have come here to learn CSS then you must be familiar with HTML but if you do not have any idea then that's not a problem. You can go to our <a href="html-tutorial"><strong>HTML tutorial</strong></a> and learn it from there.</p><p>We can say that HTML is a markup language used to design the basic structure of a web page which means no alignment of elements, no color, no formatting, etc. What do you think the appearance of the page will be like? The answer is that the page will look unattractive, won't it? CSS comes into the picture when we want to make the page look attractive. CSS stands for <strong>Cascading Style Sheets</strong> which is one of the important pillars of web development.</p><p>This <strong>CSS tutorial</strong> or<strong> CSS3 tutorial</strong> provides basic and advanced concepts of CSS technology. Our CSS tutorial is developed for both beginners and professionals.</p><img alt="CSS tutorial" src="https://images.tpointtech.com/csspages/images/css-tutorial-1.png"><h2 class="h2">What is CSS?</h2><p>The major points of CSS are given below:</p><ul class="points"><li>CSS stands for Cascading Style Sheet.</li><li>CSS is a widely used language on the web.</li><li>CSS helps web designers to apply style to <a href="html-tags">HTML tags</a>.</li><li>CSS is utilized to make a responsive website.</li></ul><h2 class="h2">How does CSS help to improve a website?</h2><p>We will comprehend this with the help of an example.</p><p>Let us write the HTML code:</p><div class="codewrapper"><h3 class="h3">Example</h3><div class="codeblock"><textarea class="xml" name="code">&lt;p&gt;Hello Everyone!&lt;/p&gt;
</textarea></div><a class="btn btn-apna" href="https://www.tpointtech.com/html/tryit?program=css-tutorial-1" target="_blank">Execute Code</a></div><p><strong>Output:</strong></p><img alt="CSS tutorial" src="https://images.tpointtech.com/csspages/images/css-tutorial-2.png"><p>The text looks plain without CSS. Now, we will use CSS to enhance the look of the text.</p><p>Let us write the CSS code inside the &lt;style&gt; tag:</p><div class="codewrapper"><h3 class="h3">Example</h3><div class="codeblock"><textarea class="xml" name="code">&lt;!DOCTYPE html&gt;
&lt;html&gt;
  &lt;head&gt;
    &lt;title&gt;CSS&lt;/title&gt;
    &lt;style&gt;
    body {
        background-color: rgb(249, 207, 252);
    }
    p {
        font-family: sans-serif;
        font-size: 20px;
        color: rgb(24, 4,105);
        font-weight: bold;
    }
    &lt;/style&gt;
  &lt;/head&gt;
  &lt;body&gt;
      &lt;p&gt;Hello Everyone!&lt;/p&gt;
  &lt;/body&gt;
&lt;/html&gt;
</textarea></div><a class="btn btn-apna" href="https://www.tpointtech.com/html/tryit?program=css-tutorial-2" target="_blank">Execute Code</a></div><p><strong>Output:</strong></p><img alt="CSS tutorial" src="https://images.tpointtech.com/csspages/images/css-tutorial-3.png"><p>Now we can clearly see that after writing the CSS code, the text appears colourful and larger. The background is also colorful. That's how CSS improves a website and makes it look better. That is the magic of CSS.</p><h2 class="h2">Why learn CSS?</h2><img alt="CSS tutorial" src="https://images.tpointtech.com/csspages/images/css-tutorial-4.png"><ul class="points"><li><strong>Creating Beautiful Websites:</strong> The structure of the web page is created using HTML but if you want to make a colourful website then CSS is used. It controls the visual style of the page. It adds colors, fonts, animations and more to HTML tags.</li><li><strong>Making Responsive Websites:</strong> CSS is used to make responsive websites which means it makes mobile-friendly design that adapts to all sizes of screens such as phones, laptops, tablets, etc.</li><li><strong>Customizing Anything:</strong> It is utilized to customize web pages like creating a dark theme, stylish menus, animated text and more.</li><li><strong>Boosting your Career: </strong>If you want to be a web developer or UI/UX designer then you must learn CSS because it is a must-have skill in the tech world.</li></ul><h2 class="h2">Applications of CSS</h2><img alt="CSS tutorial" src="https://images.tpointtech.com/csspages/images/css-tutorial-5.png"><p><strong>Styling Web Pages: </strong>CSS is used to style the <a href="html-elements">HTML elements</a> on the web pages such as text color, background color, fonts, layouts, spacing, borders, animation, etc. The CSS controls and enhances the look of the web page to make it interactive and engaging.</p><p><strong>Responsive Design:</strong> CSS is utilized to make web pages fit different sizes of screens such as mobile, laptop, tablet, etc. We can use CSS media queries to make responsive web pages for a better user experience for different devices.</p><p><strong>Animations and Transitions: </strong>CSS is utilized to create smooth effects on a web page to make it more interactive, even without the help of JavaScript. It is used to create the impact like hover effects, button click animations, fade-ins, etc.</p><p><strong>Website Management:</strong> CSS helps to manage and maintain the style of the website efficiently. A separate file of CSS can be generated other than an HTML file. If, in the future, you want to update the designs of a website then you can change the designs such as updating font style, background color, etc., in the CSS file which helps in saving time and effort.</p><p><strong>Accessibility Improvement: </strong>CSS helps in creating accessible web pages by giving permission to alter the style without affecting the underlying HTML. CSS makes content readable, font scaling, etc. CSS helps in making websites usable for people with disabilities such as giving alt text for images, color contrast modes, etc.</p><p><strong>Custom Themes: </strong>CSS allows to create the custom themes such as light or dark modes. This design gives control to users so that they can adjust the site's appearance.</p><p><strong>Social Media:</strong> CSS is utilized in making social media design. It can create a share button and feed previews to make the appealing page. Many social media have already used it such as Twitter, Facebook, Instagram, etc.</p><p><strong>E-Commerce:</strong> CSS is utilized to make visually attractive product pages, shopping carts, checkout forms, etc. It creates a clean interface which gains the trust of users. It is utilized to create designs such as highlighted discounts, buy buttons, etc., to attract users.</p><p><strong>Framework Integration:</strong> CSS works with frameworks such as <a href="tailwind-css-in-react">Tailwind CSS</a>, <a href="bootstrap-5">Bootstrap</a>, <a href="materialize-css-tutorial">Materialize</a>, etc. These frameworks contain predefined classes and utilities that help speed up the creation of responsive websites.</p><h2 class="h2">CSS Versions</h2><p>There are several <a href="css-latest-version">versions of CSS</a>. They are as follows:</p><img alt="CSS tutorial" src="https://images.tpointtech.com/csspages/images/css-tutorial-6.png"><ul class="points"><li><strong>CSS1</strong>: It is the first version, which was introduced on <strong>December 17, 1996</strong>. The features it brought were basic styling properties for font, texts and the concepts of selectors.</li><li><strong>CSS2</strong>: It is the second version, which was introduced on<strong> May 12, 1998. </strong>The features it brought were display property, pseudo-classes, pseudo-elements, etc.</li><li><strong>2.1</strong>: It is the third version, which was introduced on <strong>June 7, 2011</strong>. The features it brought were colour properties, e.g., rgba(), hsl(). This version standardized box model properties and improved cross-browser compatibility.</li><li><strong>CSS3</strong>: The fourth version, which was introduced at the start of<strong> 1999</strong>. It is the latest version. It brought the collection of modules, such as Selector, Box-Model, Backgrounds and Borders, 2DTransformations, Grid Layout, etc.</li><li><strong>CSS4 (Upcoming): </strong>CSS4 is an upcoming version. The particular modules and features are in development. It may add some improvement to the existing modules and new features.</li><li><strong>CSS5 (Planned): </strong>It is not officially announced but represents the future development of CSS. It will include further enhancements and capabilities.</li></ul><h2 class="h2">Types of CSS</h2><p>There are basically three types of CSS. They are as follows:</p><img alt="CSS tutorial" src="https://images.tpointtech.com/csspages/images/css-tutorial-7.png"><p><strong>1. Inline CSS: </strong>It is defined straight to an HTML element in the HTML file. The <strong>style attribute</strong> is used to apply it. The <a href="inline-css">inline CSS</a> has the highest priority.</p><p><strong>Example:</strong></p><p>In the example below, we will give color to the text utilizing inline CSS.</p><p><strong>Code:</strong></p><div class="codewrapper"><h3 class="h3">Example</h3><div class="codeblock"><textarea class="xml" name="code">&lt;!DOCTYPE html&gt;
&lt;html&gt;
&lt;head&gt;
&lt;title&gt;My Page&lt;/title&gt;
&lt;/head&gt;
&lt;body&gt;
&lt;h1 style="color: red;"&gt;Hello, CSS!&lt;/h1&gt;
&lt;/body&gt;
&lt;/html&gt;
</textarea></div><a class="btn btn-apna" href="https://www.tpointtech.com/html/tryit?program=css-tutorial-3" target="_blank">Execute Code</a></div><p><strong>Output:</strong></p><img alt="CSS tutorial" src="https://images.tpointtech.com/csspages/images/css-tutorial-8.png"><p><strong>2. Internal CSS</strong>: The code of <a href="internal-css">internal CSS</a> is written in the HTML file by the developers. The <a href="html-style">&lt;style&gt; tag</a> is utilized by the developer to define it. In the &lt;head&gt; tag, the &lt;style&gt; tag is defined, and within that, we write CSS code.</p><p><strong>Example</strong>:</p><p>In the example below, we will give color and font-family to the text utilizing Internal CSS.</p><p><strong>Code:</strong></p><div class="codewrapper"><h3 class="h3">Example</h3><div class="codeblock"><textarea class="xml" name="code">&lt;!DOCTYPE html&gt;
&lt;html&gt;
&lt;head&gt;
&lt;title&gt;My Page&lt;/title&gt;
&lt;style&gt;
   h1{
    color: blue;
    font-family: Cursive;
   } 
&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
&lt;h1&gt;Hello, CSS! &lt;/h1&gt;
&lt;/body&gt;
&lt;/html&gt;  
</textarea></div><a class="btn btn-apna" href="https://www.tpointtech.com/html/tryit?program=css-tutorial-4" target="_blank">Execute Code</a></div><p><strong>Output:</strong></p><img alt="CSS tutorial" src="https://images.tpointtech.com/csspages/images/css-tutorial-9.png"><p><strong>3. External CSS: </strong>A separate file is created to define the <a href="external-css">external CSS</a> using <strong>.CSS extension</strong>. The <a href="html-link-tag">&lt;link&gt; tag</a> is utilized by the developer to link this file to the HTML document. External CSS is the recommended method to define CSS for large projects because it makes it easy to maintain and update the style across several pages.</p><p><strong>Example:</strong></p><p>In the below example, we will give color and font-family to the text utilizing External CSS. We will define the relationship between HTML and CSS utilizing the &lt;link&gt; tag.</p><p><strong>HTML Code File:</strong></p><div class="codewrapper"><h3 class="h3">Example</h3><div class="codeblock"><textarea class="xml" name="code">&lt;!DOCTYPE html&gt;
&lt;html&gt;
&lt;head&gt;
&lt;title&gt;My Page&lt;/title&gt;
  &lt;link rel="stylesheet" href="styles.css"&gt;
&lt;/head&gt;
&lt;body&gt;
&lt;h1&gt;Hello, CSS! &lt;/h1&gt;
&lt;/body&gt;
&lt;/html&gt; 
</textarea></div></div><p><strong>styles.css File:</strong></p><div class="codeblock"><textarea class="xml" name="code">h1{
    color: green;
    font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
}
</textarea></div><p><strong>Output:</strong></p><img alt="CSS tutorial" src="https://images.tpointtech.com/csspages/images/css-tutorial-10.png"><h4 class="n">Note: The style of inline CSS has a higher priority among the three. The internal CSS has more priority than the external CSS.</h4><h2 class="h2">CSS Properties</h2><p>The CSS properties are the backbone of web design. It is used to define the structure or layout of the web page, and it controls the behavior of HTML elements.</p><p>The list of some basic properties is given below:</p><h3 class="h3">Text Properties</h3><table class="alt"><tbody><tr><th>Property</th><th>Descriptions</th></tr><tr><td>color</td><td>It sets the text color.</td></tr><tr><td>text-align</td><td>It horizontally aligns the text. e.g., left, right, center, justify.</td></tr><tr><td>line-height</td><td>It is utilized by the developer to give the gap between lines.</td></tr><tr><td>letter-spacing</td><td>It is utilized by the developer to give the spaces between characters.</td></tr><tr><td>text-decoration</td><td>It is utilized by the developer to decorate the text e.g., none, underline, etc.</td></tr><tr><td>text-transform</td><td>It is utilized by the developer to define the uppercase and lowercase letters in a text.</td></tr></tbody></table><h3 class="h3">Font Properties:</h3><table class="alt"><tbody><tr><th>Property</th><th>Descriptions</th></tr><tr><td>font</td><td>It is a shorthand property which is utilized by the developer to give all the font-properties in one declaration.</td></tr><tr><td>font-family</td><td>It is utilized by the developer to give the font family.</td></tr><tr><td>font-size</td><td>It is utilized by the developer to give the size to text.</td></tr><tr><td>font-style</td><td>It is utilized by the developer to style the text.</td></tr><tr><td>font-weight</td><td>It is utilized by the developer to specify the weight of a font such as thickness and boldness.</td></tr></tbody></table><h3 class="h3">List Properties:</h3><table class="alt"><tbody><tr><th>Property</th><th>Descriptions</th></tr><tr><td>list-style</td><td>It is a shorthand property which is utilized to set all properties in one declaration.</td></tr><tr><td>list-style-type</td><td>It is utilized by the developer to define the type of list-item, e.g., none, disc, square, circle, etc.</td></tr><tr><td>list-style-position</td><td>It is utilized to define the position of the list-item markers.</td></tr><tr><td>list-style-image</td><td>It is utilized by the developer to define an image as the list-item marker.</td></tr></tbody></table><h3 class="h3">Border Properties:</h3><table class="alt"><tbody><tr><th>Property</th><th>Descriptions</th></tr><tr><td>border</td><td>It is a shorthand property for border width, style and color. It is utilized by the developer to set the border properties in one declaration.</td></tr><tr><td>border-width</td><td>It is utilized to give width to all borders.</td></tr><tr><td>border-color</td><td>It is utilized by the developer to give the color to all the borders of a box.</td></tr><tr><td>border-style</td><td>It is utilized by the developer to style all borders of the box.</td></tr><tr><td>border-bottom</td><td>It is a shorthand property for bottom border width, style and color utilized by the developer to set the bottom border properties in one declaration.</td></tr><tr><td>border-bottom-width</td><td>It is utilized to give width to bottom border.</td></tr><tr><td>border-bottom-color</td><td>The developer makes use of it to give the color to the bottom border.</td></tr><tr><td>border-bottom-style</td><td>The developer makes use of it to style the bottom border.</td></tr><tr><td>border-left</td><td>It is a shorthand property left border width, style and color utilized by the developer to set all the properties of the left-border in one declaration.</td></tr><tr><td>border-left-width</td><td>It is utilized to give width to left border.</td></tr><tr><td>border-left-color</td><td>It is utilized by the developer to give the color to the left border.</td></tr><tr><td>border-left-style</td><td>It is utilized by the developer to style the left border.</td></tr><tr><td>border-right</td><td>It is a shorthand property for right border width, style and color utilized by the developer to set all the right border properties in one declaration.</td></tr><tr><td>border-right-width</td><td>It is utilized to give width to right border.</td></tr><tr><td>border-right-color</td><td>The developer makes use of it to give the color to the right-border.</td></tr><tr><td>border-right-style</td><td>It is utilized by the developer to style the right border.</td></tr><tr><td>border-top</td><td>It is a shorthand property for top border width, style and color utilized by the developer to set all the top border properties in one declaration.</td></tr><tr><td>border-top-width</td><td>It is utilized to give width to top border.</td></tr><tr><td>border-top-color</td><td>The developer makes use of it to give the color to the top border.</td></tr><tr><td>border-top-style</td><td>It is utilized by the developer to style the top border.</td></tr></tbody></table><h2 class="h2">Career Opportunity of learning CSS</h2><p>After learning CSS, there are multiple career opportunities in <strong>Web development and design</strong>. CSS is a foundation skill for <strong>front-end development</strong>. If you want to build your career in the field of <strong>front-end development, web design, UX/ UI design, email development/ Design, </strong>etc., then you must learn this important skill.</p><p>CSS is used in frameworks and libraries like <strong>React.js, Vue.js, etc</strong>. These days, the demand for <strong>user-friendly digital experiences </strong>has arisen. Therefore, the companies are expecting that a candidate can style and optimize interfaces so CSS plays a vital role in web development.</p><h2 class="h2">Conclusion:</h2><p>In this article, we have learnt CSS. We have covered various topics like all the versions of CSS, three <a href="types-of-css">types of CSS</a>, its properties and career opportunities. CSS is one of the important skills for developing a front-end website.</p><h2 class="h2">FAQs:</h2><p>Some of the frequently asked questions are given below:</p><p><strong>1. What distinguishes between id and class?</strong></p><p>The <a href="css-class-vs-id">difference between id and class</a> is that the <strong>id</strong> is the unique identity of an element whereas the same <strong>class </strong>can be given to multiple elements which means we can group all the same class elements and apply the same style.</p><p><strong>2. What are CSS Selectors?</strong></p><p>It is used to select elements based on their <strong>name, ID, attributes, class, tags, etc</strong>.</p><p><strong>3. What is the Box model?</strong></p><p>Every element in HTML is wrapped around a <a href="css-box-model">box model</a>. A box model consists of the following:</p><ul class="points"><li><strong>Content:</strong> It is the content, <strong>g., text, images etc</strong>.</li><li><strong>Padding:</strong> It is a whitespace around the content.</li><li><strong>Border:</strong> It is around the padding.</li><li><strong>Margin:</strong> It is around the border.</li></ul><p><strong>4. How can you integrate CSS into an HTML Page?</strong></p><p>There are three methods to integrate CSS into an HTML page. They are as follows:</p><ul class="points"><li>Inline CSS</li><li>Internal CSS</li><li>External CSS</li></ul><p><strong>5. How can you make a website responsive?</strong></p><p><a href="css-media-query">CSS Media query</a> is utilized to make a website responsive. The syntax is:</p><div class="codeblock"><textarea class="xml" name="code">@media media-type and (condition) {
    // CSS Code
}
</textarea></div><div class="index"><h2 class="h2">CSS Basics</h2><ul class="points"><li><a href="css-tutorial">Introduction to CSS</a></li><li><a href="what-is-css">What is CSS</a></li><li><a href="css-syntax">CSS Syntax</a></li><li><a href="css-selector">CSS Selector</a></li><li><a href="how-to-add-css">How to Add CSS</a></li><li><a href="inline-css">Inline CSS</a></li><li><a href="internal-css">Internal CSS</a></li><li><a href="external-css">External CSS</a></li><li><a href="css-comments">CSS Comments</a></li></ul><h2 class="h2">CSS Properties</h2><ul class="points"><li><a href="/css-background">CSS Background</a></li><li><a href="/css-border">CSS Border</a></li><li><a href="/css-border-radius-property">CSS border-radius</a></li><li><a href="/css-border-collapse-property">CSS border-collapse</a></li><li><a href="/css-border-spacing-property">CSS border-spacing</a></li><li><a href="/css-display">CSS Display</a></li><li><a href="/css-cursor">CSS Cursor Property with Example</a></li><li><a href="/css-buttons">CSS Buttons</a></li><li><a href="/css-float">CSS Float</a></li><li><a href="/css-font">CSS Font</a></li><li><a href="/css-font-size">CSS Font-size</a></li><li><a href="/css-font-family">CSS font-family</a></li><li><a href="/css-font-weight">CSS font-weight</a></li><li><a href="/css-font-stretch-property">CSS font-stretch</a></li><li><a href="/css-colors">CSS Colors</a></li><li><a href="/css-hover">CSS Hover</a></li><li><a href="/css-important">CSS Important</a></li><li><a href="/css-background-color">CSS Background-color</a></li><li><a href="/css-background-attachment-property">background-attachment</a></li><li><a href="/css-background-size-property">background-size</a></li><li><a href="/css-line-height">CSS Line Height</a></li><li><a href="/css-margin">CSS Margin</a></li><li><a href="/css-opacity">CSS Opacity</a></li><li><a href="/css-filter">CSS filter</a></li><li><a href="/css-images">CSS Images</a></li><li><a href="/css-overflow">CSS Overflow</a></li><li><a